function creerFilePriorite() {
  // internal heap: array of {valeur, priorite}
  const tas = [];

  function _swap(i, j) {
    [tas[i], tas[j]] = [tas[j], tas[i]];
  }

  function _heapifyUp(index) {
    while (index > 0) {
      const parentIdx = Math.floor((index - 1) / 2);
      if (tas[parentIdx].priorite <= tas[index].priorite) break;
      _swap(parentIdx, index);
      index = parentIdx;
    }
  }

  function _heapifyDown(index) {
    const last = tas.length - 1;
    while (true) {
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      let smallest = index;

      if (left <= last && tas[left].priorite < tas[smallest].priorite) smallest = left;
      if (right <= last && tas[right].priorite < tas[smallest].priorite) smallest = right;
      if (smallest === index) break;
      _swap(index, smallest);
      index = smallest;
    }
  }

  return {
    enqueue(valeur, priorite) {
      tas.push({ valeur, priorite });
      _heapifyUp(tas.length - 1);
    },
    dequeue() {
      if (tas.length === 0) return undefined;
      const racine = tas[0];
      const dernier = tas.pop();
      if (tas.length > 0) {
        tas[0] = dernier;
        _heapifyDown(0);
      }
      return racine.valeur;
    },
    taille() {
      return tas.length;
    }
  };
}
