function creerEventEmitter() {
  const listeners = new Map(); // event => Array<fn>

  return {
    on(event, fn) {
      if (!listeners.has(event)) listeners.set(event, []);
      listeners.get(event).push(fn);
      return this; // allow chaining
    },
    off(event, fn) {
      if (!listeners.has(event)) return this;
      const fnList = listeners.get(event);
      const idx = fnList.indexOf(fn);
      if (idx !== -1) fnList.splice(idx, 1);
      // optional: clean up empty arrays
      if (fnList.length === 0) listeners.delete(event);
      return this;
    },
    emit(event, ...args) {
      if (!listeners.has(event)) return this;
      // copy array to avoid issues if listeners modify list during emit
      const fnList = listeners.get(event).slice();
      for (const fn of fnList) {
        fn.apply(this, args);
      }
      return this;
    }
  };
}
