function creerProxy(cible, gestionnaire) {
  // Manual proxy: returns an object that delegates get/set to the handler.
  // Property access is intercepted via the wrapper's own get/set methods.
  // For direct property reads/writes we rely on the wrapper's methods.
  const wrapper = {};

  // Define a generic getter that uses the handler if present.
  Object.defineProperty(wrapper, '__proto__', {
    value: null,
    writable: false,
    enumerable: false,
    configurable: true
  });

  // Proxy-like get and set are exposed as methods.
  wrapper.get = function (prop) {
    if (typeof gestionnaire.get === 'function') {
      return gestionnaire.get(cible, prop, wrapper);
    }
    return cible[prop];
  };

  wrapper.set = function (prop, valeur) {
    if (typeof gestionnaire.set === 'function') {
      gestionnaire.set(cible, prop, valeur, wrapper);
    } else {
      cible[prop] = valeur;
    }
    return wrapper; // allow chaining
  };

  // Also forward other properties of the target (non-intercepted) for convenience.
  Object.keys(cible).forEach(key => {
    if (!(key in wrapper)) {
      Object.defineProperty(wrapper, key, {
        get: () => wrapper.get(key),
        set: v => wrapper.set(key, v),
        enumerable: true,
        configurable: true
      });
    }
  });

  return wrapper;
}
```

