function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'CLOSED'; // CLOSED, OPEN, HALF_OPEN
  let failureCount = 0;
  let lastFailureTime = 0;

  return async function (...args) {
    const now = Date.now();

    if (state === 'OPEN') {
      if (now - lastFailureTime < delaiResetMs) {
        return Promise.reject(new Error('Circuit breaker is OPEN'));
      }
      state = 'HALF_OPEN';
    }

    try {
      const result = await fn(...args);
      if (state === 'HALF_OPEN') {
        state = 'CLOSED';
        failureCount = 0;
      }
      return result;
    } catch (err) {
      failureCount++;
      lastFailureTime = now;
      if (state === 'CLOSED' && failureCount >= seuil) {
        state = 'OPEN';
      } else if (state === 'HALF_OPEN') {
        state = 'OPEN';
      }
      throw err;
    }
  };
}
```

